import { forwardRef, useEffect, useImperativeHandle, useRef } from "react";

/* PARTICLE SPILL — a 2D overlay across the Experience hero.
   When the logo bursts, a small handful of its particles arc across to
   the "Experience" letters, touch their top edges and, without
   stopping, slide off and drop under gravity, fading as they fall.
   On the way down they hit the elements below the heading (the
   "Currently" pill, the chips, the buttons): each impact bounces the
   particle off the element's top edge with a small spark, and the
   element gives a short glow. */

const GRAVITY = 650; // px/s² (gentle: they drift down rather than drop)
const FLY = 0.8; // s to reach the letters (plus a stagger)
const MAX_PARTS = 180; // a sprinkle
const SLIDE = 0.9; // s sliding slowly along the letter before falling
const FADE = 2.4; // s to fade once released
const OBSTACLES = ".exp-current-pill, .exp-hero-chip, .xh-cta";
const MAX_HITS = 2; // bounces per particle
const HIT_COOLDOWN = 260; // ms between glows on one element

// Points on the top surfaces of the heading's glyphs, in element coords.
function glyphTops(el) {
  const r = el.getBoundingClientRect();
  const w = Math.ceil(r.width);
  const h = Math.ceil(r.height);
  if (!w || !h) return [];
  const cs = getComputedStyle(el);
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  const g = c.getContext("2d", { willReadFrequently: true });
  g.font = `${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
  g.fillStyle = "#000";
  g.textBaseline = "alphabetic";
  const m = g.measureText(el.textContent);
  const asc = m.fontBoundingBoxAscent || m.actualBoundingBoxAscent;
  const desc = m.fontBoundingBoxDescent || m.actualBoundingBoxDescent;
  g.fillText(el.textContent, 0, (h + asc - desc) / 2);
  const d = g.getImageData(0, 0, w, h).data;
  const tops = [];
  for (let x = 0; x < w; x += 2) {
    let prev = false;
    for (let y = 0; y < h; y++) {
      const ink = d[(y * w + x) * 4 + 3] > 128;
      if (ink && !prev) tops.push([x, y]); // an edge where ink starts
      prev = ink;
    }
  }
  return tops;
}

const hexToRgb = (hex) => {
  const n = parseInt(hex.replace("#", ""), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
};

const ParticleSpill = forwardRef(function ParticleSpill({ targetRef }, ref) {
  const canvasRef = useRef(null);
  const state = useRef({ parts: [], sparks: [], raf: 0, last: 0, hitAt: new Map() });

  // Brief glow on an element that was hit (throttled per element).
  const flash = (el, now) => {
    const st = state.current;
    if (now - (st.hitAt.get(el) || 0) < HIT_COOLDOWN) return;
    st.hitAt.set(el, now);
    el.classList.remove("xh-hit");
    void el.offsetWidth; // restart the animation
    el.classList.add("xh-hit");
  };

  const loop = (now) => {
    const st = state.current;
    const cv = canvasRef.current;
    if (!cv) return;
    const dt = Math.min(0.05, Math.max(0, (now - st.last) / 1000));
    st.last = now;
    const g = cv.getContext("2d");
    const dpr = cv.width / cv.clientWidth || 1;
    g.setTransform(dpr, 0, 0, dpr, 0, 0);
    g.clearRect(0, 0, cv.clientWidth, cv.clientHeight);
    const floor = cv.clientHeight - 6;
    // obstacle top edges, in canvas coords (they can move with layout)
    const cr = cv.getBoundingClientRect();
    const host = cv.parentElement;
    const obs = host
      ? [...host.querySelectorAll(OBSTACLES)].map((el) => {
          const r = el.getBoundingClientRect();
          return { el, l: r.left - cr.left + 6, r: r.right - cr.left - 6, top: r.top - cr.top };
        })
      : [];
    let alive = 0;
    st.parts.forEach((p) => {
      p.t += dt;
      if (p.t < p.delay) return;
      const t = p.t - p.delay;
      if (t < FLY) {
        // arc from the logo to the letter top (quadratic, lifted mid-way)
        const u = t / FLY;
        const e = 1 - Math.pow(1 - u, 3);
        const mx = (p.sx + p.tx) / 2;
        const my = Math.min(p.sy, p.ty) - p.lift;
        p.x = (1 - e) * (1 - e) * p.sx + 2 * (1 - e) * e * mx + e * e * p.tx;
        p.y = (1 - e) * (1 - e) * p.sy + 2 * (1 - e) * e * my + e * e * p.ty;
        p.a = Math.min(1, u * 3);
      } else {
        // touched the letter: slide slowly along its edge, then ease off
        // and drift down, fading out
        if (!p.falling) {
          p.falling = true;
          p.vx = (Math.random() < 0.5 ? -1 : 1) * (12 + Math.random() * 22);
          p.vy = 6 + Math.random() * 8;
        }
        const slid = t - FLY;
        const released = slid > SLIDE + p.seed * 0.004;
        if (released) {
          p.vy += GRAVITY * dt;
          p.a -= dt / FADE;
        }
        p.vx *= 1 - dt * 0.8;
        const prevY = p.y;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        // hit: crossed an element's top edge while falling
        if (released && p.vy > 0 && p.hits < MAX_HITS) {
          for (let o = 0; o < obs.length; o++) {
            const b = obs[o];
            if (prevY <= b.top && p.y >= b.top && p.x > b.l && p.x < b.r) {
              p.y = b.top - 0.5;
              p.vy *= -(0.3 + Math.random() * 0.2);
              p.vx += (Math.random() - 0.5) * 140;
              p.hits += 1;
              st.sparks.push({ x: p.x, y: b.top, t: 0, c: p.c });
              flash(b.el, now);
              break;
            }
          }
        }
        if (p.y > floor) p.a = 0;
      }
      if (p.a <= 0) return;
      alive += 1;
      g.fillStyle = `rgba(${p.c[0]},${p.c[1]},${p.c[2]},${Math.max(0, p.a).toFixed(3)})`;
      g.fillRect(p.x - p.s / 2, p.y - p.s / 2, p.s, p.s);
    });
    // impact sparks: a small ring that opens and fades
    st.sparks = st.sparks.filter((sp) => (sp.t += dt) < 0.4);
    st.sparks.forEach((sp) => {
      const u = sp.t / 0.4;
      g.strokeStyle = `rgba(${sp.c[0]},${sp.c[1]},${sp.c[2]},${(1 - u) * 0.9})`;
      g.lineWidth = 1.2;
      g.beginPath();
      g.ellipse(sp.x, sp.y, 2 + u * 9, 1 + u * 3, 0, 0, Math.PI * 2);
      g.stroke();
    });
    if (alive || st.sparks.length || st.parts.some((p) => p.t < p.delay)) {
      st.raf = requestAnimationFrame(loop);
    } else {
      st.parts = [];
      st.raf = 0;
      g.clearRect(0, 0, cv.clientWidth, cv.clientHeight);
    }
  };

  useImperativeHandle(ref, () => ({
    burst(points, color) {
      const cv = canvasRef.current;
      const el = targetRef?.current;
      if (!cv || !el || !points?.length) return;
      const cr = cv.getBoundingClientRect();
      const er = el.getBoundingClientRect();
      // skip when the heading isn't on screen
      if (er.bottom < 0 || er.top > window.innerHeight) return;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      if (cv.width !== Math.round(cr.width * dpr) || cv.height !== Math.round(cr.height * dpr)) {
        cv.width = Math.round(cr.width * dpr);
        cv.height = Math.round(cr.height * dpr);
      }
      const tops = glyphTops(el);
      if (!tops.length) return;
      const rgb = hexToRgb(color || "#2962ff");
      const light = rgb.map((v) => Math.min(255, v + 90));
      const st = state.current;
      // only a sprinkle of the logo travels
      const pick = points.filter((_, i) => i % Math.max(1, Math.floor(points.length / MAX_PARTS)) === 0).slice(0, MAX_PARTS);
      pick.forEach(([x, y], i, arr) => {
        const [gx, gy] = tops[Math.floor(Math.random() * tops.length)];
        st.parts.push({
          sx: x - cr.left,
          sy: y - cr.top,
          tx: er.left - cr.left + gx,
          ty: er.top - cr.top + gy - 1.5,
          x: x - cr.left,
          y: y - cr.top,
          lift: 60 + Math.random() * 120,
          delay: (i / arr.length) * 0.5 + Math.random() * 0.15,
          t: 0,
          a: 0,
          s: 2 + Math.random() * 1.6,
          c: Math.random() < 0.3 ? light : rgb,
          seed: Math.random() * 100,
          vx: 0,
          vy: 0,
          falling: false,
          hits: 0,
        });
      });
      if (!st.raf) {
        st.last = performance.now();
        st.raf = requestAnimationFrame(loop);
      }
    },
  }));

  useEffect(() => () => cancelAnimationFrame(state.current.raf), []);

  return <canvas ref={canvasRef} className="xh-spill" aria-hidden="true" />;
});

export default ParticleSpill;
